import pathlib,sys,json,time,subprocess,re,xml.etree.ElementTree as ET
root=pathlib.Path.cwd();sys.path.insert(0,str(root/'tools'));from device_cdp import Device,ADB
w=root.parents[1]/'work';d=Device();checks=[]
def check(name,code,ok=bool):
 v=d.evaluate(code);passed=ok(v);checks.append({'test':name,'passed':passed,'evidence':v});print('PASS'if passed else 'FAIL',name,flush=True);assert passed,str(v)[:600]
def adb(*args):return subprocess.check_output([ADB,*map(str,args)])
def tap(selector):
 b=d.evaluate('(()=>{const r=document.querySelector('+json.dumps(selector)+').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,s:devicePixelRatio};})()');adb('shell','input','tap',round(b['x']*b['s']),round(58+b['y']*b['s']));time.sleep(.15)
try:
 assert d.evaluate("forge.state.project.startsWith('input-check-')")
 check('Full first-run setup downloaded and installed canonical packs over HTTPS', '(async()=>{const s=await native("toolPacks");return{complete:forge.settings.setupComplete,packs:s.packs.map(p=>({id:p.id,installed:p.installed}))};})()',lambda v:v['complete']and all(p['installed']for p in v['packs']))
 check('Locally computed indentation guides and fixed breakpoint gutter',r'''(async()=>{await forge.openFile(forge.state.root+'/main.cpp');forge.active.model.setValue('int main() {\n    for (int i = 0; i < 3; ++i) {\n        if (i > 0) {\n            (void)i;\n        }\n    }\n}\n');await forge.saveAll();await new Promise(r=>setTimeout(r,250));const before=await native('editorVisualState');await forge.debugger.toggleBreakpoint(forge.active.model,4);await new Promise(r=>setTimeout(r,150));const after=await native('editorVisualState');return{before,after};})()''',lambda v:v['before']['guides']>=3 and v['before']['tabWidth']==4 and v['before']['textOffset']==v['after']['textOffset']and v['before']['sideIcons'])
 check('File tabs keep a compact 36 CSS pixel height',"document.querySelector('.tab').getBoundingClientRect().height",lambda v:35.9<=v<=36.1)
 # Hover pseudo state must not widen the divider.
 b=d.evaluate("(()=>{const e=document.querySelector('#sidebarResizer'),r=e.getBoundingClientRect();return{x:r.x+3,y:r.y+100,width:r.width};})()")
 d.call('Input.dispatchMouseEvent',{'type':'mouseMoved','x':b['x'],'y':b['y']});check('Hover preserves the narrow divider width',"document.querySelector('#sidebarResizer').getBoundingClientRect().width",lambda v:abs(v-b['width'])<.1 and v<=6.1)
 d.evaluate("StudioChoices.open(document.querySelector('#standardSelect'));window.pickerOld=forge.settings.cppStandard")
 # This row lies over the native editor: Android must pass the tap through its clipped popup.
 tap('.studio-choice-popover [data-value="c++23"]')
 check('Actual Android touch selects an anchored option over the native editor',"({selected:document.querySelector('#standardSelect').value,closed:!StudioChoices.active,modal:!!document.querySelector('dialog[open]')})",lambda v:v['selected']=='c++23'and v['closed']and not v['modal'])
 d.evaluate("forge.changeSettings({cppStandard:pickerOld})")
 check('Separate folder toolbar button creates a real nested folder',r'''(async()=>{window.folderProbe='folders-'+Date.now()+'/nested';document.querySelector('#newFolderButton').click();await new Promise(r=>setTimeout(r,80));document.querySelector('#inputValue').value=folderProbe;document.querySelector('#inputDialog').close('ok');await new Promise(r=>setTimeout(r,250));return JSON.stringify(await native('tree')).includes(folderProbe.split('/')[0]);})()''')
 check('C++ Studio and CLion remain separate formatter presets',r'''(async()=>{const p=await native('formatterPresets');const r=await native('formatterPreview',{style:p.studio,text:'void f(auto & v){for(auto & el:v){auto*ptr=&el;}}'});return{studio:p.studio,clion:p.clion,text:r.text,code:r.code};})()''',lambda v:v['code']==0 and'auto& el : v'in v['text']and'auto *ptr'in v['text']and v['studio']!=v['clion'])
 check('Template files honor the configured UTF-16LE encoding',r'''(async()=>{const old=forge.settings.defaultEncoding;try{forge.settings.defaultEncoding='UTF-16LE';await native('settings',forge.settings);const rows=await native('createTemplate',{kind:'hpp',name:'encoding-'+Date.now(),namespace:''});const r=await native('read',{path:rows[0].path});return{encoding:r.encoding,text:r.text};}finally{forge.settings.defaultEncoding=old;await native('settings',forge.settings);}})()''',lambda v:v['encoding']=='UTF-16LE'and'#pragma once'in v['text'])
 check('Source creation offers a valid real CMakeLists when none exists',r'''(async()=>{const path=forge.state.root+'/CMakeLists.txt',backup=path+'.test-backup';await native('renameFile',{path,to:backup});try{await forge.refreshTree();await forge.offerCreatedSource({path:forge.state.root+'/main.cpp'});document.querySelector('#createdCMakeTarget').value='executable';document.querySelector('#acceptCreatedCMake').click();for(let n=0;n<100&&document.querySelector('#createCMakeOffer').open;n++)await new Promise(r=>setTimeout(r,30));const text=(await native('read',{path})).text;const configure=await native('cmakeConfigure',{path:forge.state.root+'/main.cpp',options:{...forge.settings,compiler:'gcc'},id:'new-cmake-offer'});return{text,code:configure.code};}finally{await native('deleteFile',{path});await native('renameFile',{path:backup,to:path});await forge.refreshTree();await forge.openFile(forge.state.root+'/main.cpp');}})()''',lambda v:v['code']==0 and'add_executable(app "main.cpp")'in v['text'])
 check('First-run quick/full/custom modes and skip remain available',r'''(async()=>{await forge.openSetup();const modes=document.querySelectorAll('.setup-modes button').length;forge.setupDraft.mode='custom';forge.setupStep=1;forge.renderSetup();const clang=document.querySelector('#setupPackList input[value=clang]'),analysis=document.querySelector('#setupPackList input[value=analysis]');clang.checked=true;clang.dispatchEvent(new Event('change'));const dependency=analysis.checked;await forge.skipSetup();return{modes,dependency,closed:!document.querySelector('#setupDialog').open};})()''',lambda v:v['modes']==3 and v['dependency']and v['closed'])
 check('A file context menu and the project root expose Show in Files',r'''(()=>{forge.fileMenu(forge.active,300,200);const file=document.querySelector('#menu').textContent.includes('Показать в проводнике');document.querySelector('#menu').classList.add('hidden');document.querySelector('#projectRootMenu').click();const root=document.querySelector('#menu').textContent.includes('Показать в проводнике');document.querySelector('#menu').classList.add('hidden');return file&&root;})()''')
 check('File manager rejects paths outside the selected project',r'''(async()=>{try{await native('showInFiles',{path:forge.state.usr});return false;}catch{return true;}})()''')
finally:
 d.close();(root/'verification-tablet-polish.json').write_text(json.dumps({'device':'Xiaomi Pad 6 / Android 14','scope':'Own project only; actual Android popup tap; on-device compiler/tools and native rendering metrics','checks':checks,'passed':sum(v['passed']for v in checks),'total':len(checks)},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
